package org.apache.commons.codec.language;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.codec.EncoderException;
import org.apache.commons.codec.StringEncoder;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Caverphone_caverphone_TriageGen0Test {

    private Caverphone caverphone;

    @Before
    public void setUp() {
        caverphone = new Caverphone();
    }

    @Test
    public void testCaverphone_NullInput() {
        assertEquals("1111111111", caverphone.caverphone(null));
    }

    @Test
    public void testCaverphone_EmptyInput() {
        assertEquals("1111111111", caverphone.caverphone(""));
    }

    @Test
    public void testCaverphone_StandardWord() {
        // Testing basic transformation and the 10-digit padding
        // "apple" -> lowercase "apple" -> remove non-a-z -> remove final e "appl"
        // a->A, p->P, p->P, l->L -> "APPL" -> result truncated/padded
        String result = caverphone.caverphone("apple");
        assertTrue(result.length() == 10);
        assertTrue(result.endsWith("1111111111".substring(0, 6))); // Wait, logic says txt + 10 1s, then substring(0,10)
    }

    @Test
    public void testCaverphone_SpecialStartings() {
        // Test ^cough
        assertNotNull(caverphone.caverphone("cough"));
        // Test ^rough
        assertNotNull(caverphone.caverphone("rough"));
        // Test ^tough
        assertNotNull(caverphone.caverphone("tough"));
        // Test ^enough
        assertNotNull(caverphone.caverphone("enough"));
        // Test ^trough
        assertNotNull(caverphone.caverphone("trough"));
        // Test ^gn
        assertNotNull(caverphone.caverphone("gnat"));
        // Test ^mb
        assertNotNull(caverphone.caverphone("mbira"));
    }

    @Test
    public void testCaverphone_Replacements() {
        // Test cq -> 2q
        assertNotNull(caverphone.caverphone("cq"));
        // Test ci -> si
        assertNotNull(caverphone.caverphone("ci"));
        // Test ce -> se
        assertNotNull(caverphone.caverphone("ce"));
        // Test cy -> sy
        assertNotNull(caverphone.caverphone("cy"));
        // Test tch -> 2ch
        assertNotNull(caverphone.caverphone("tch"));
        // Test dg -> 2g
        assertNotNull(caverphone.caverphone("dg"));
        // Test tio -> sio
        assertNotNull(caverphone.caverphone("tio"));
        // Test tia -> sia
        assertNotNull(caverphone.caverphone("tia"));
        // Test ph -> fh
        assertNotNull(caverphone.caverphone("ph"));
        // Test sh -> s2
        assertNotNull(caverphone.caverphone("sh"));
    }

    @Test
    public void testCaverphone_CharacterReplacements() {
        // Test various single character replacements
        assertNotNull(caverphone.caverphone("c"));
        assertNotNull(caverphone.caverphone("q"));
        assertNotNull(caverphone.caverphone("x"));
        assertNotNull(caverphone.caverphone("v"));
        assertNotNull(caverphone.caverphone("d"));
        assertNotNull(caverphone.caverphone("b"));
        assertNotNull(caverphone.caverphone("z"));
        assertNotNull(caverphone.caverphone("j"));
    }

    @Test
    public void testCaverphone_VowelAndYLogic() {
        // Test ^[aeiou]
        assertNotNull(caverphone.caverphone("apple"));
        // Test [aeiou]
        assertNotNull(caverphone.caverphone("banana"));
        // Test ^y3
        assertNotNull(caverphone.caverphone("y3"));
        // Test ^y
        assertNotNull(caverphone.caverphone("yellow"));
        // Test y
        assertNotNull(caverphone.caverphone("fly"));
    }

    @Test
    public void testCaverphone_ComplexSequences() {
        // Test 3gh3 -> 3kh3
        assertNotNull(caverphone.caverphone("3gh3")); // Note: 3 is not a-z, so it will be removed by replaceAll("[^a-z]")
        // Let's test gh
        assertNotNull(caverphone.caverphone("gh"));
        // Test multiple s, t, p, k, f, m, n, w, h, r, l
        assertNotNull(caverphone.caverphone("ssss"));
        assertNotNull(caverphone.caverphone("tttt"));
        assertNotNull(caverphone.caverphone("pppp"));
        assertNotNull(caverphone.caverphone("kkkk"));
        assertNotNull(caverphone.caverphone("ffff"));
        assertNotNull(caverphone.caverphone("mmmm"));
        assertNotNull(caverphone.caverphone("nnnn"));
        assertNotNull(caverphone.caverphone("www"));
        assertNotNull(caverphone.caverphone("hhh"));
        assertNotNull(caverphone.caverphone("rrr"));
        assertNotNull(caverphone.caverphone("lll"));
    }

    @Test
    public void testCaverphone_EdgeCases() {
        // Test non-alphabetical characters
        assertEquals(caverphone.caverphone("a!b@c#d$"), caverphone.caverphone("abcd"));
        // Test case sensitivity
        assertEquals(caverphone.caverphone("ABC"), caverphone.caverphone("abc"));
        // Test final e removal (2.0 logic)
        // "ace" -> "ac" (after e removal) -> "ak" -> "ak1111111111" -> "ak11111111"
        String res = caverphone.caverphone("ace");
        assertNotNull(res);
        // Test final w removal (2.0 logic)
        assertNotNull(caverphone.caverphone("low"));
        // Test final r removal (2.0 logic)
        assertNotNull(caverphone.caverphone("car"));
        // Test final l removal (2.0 logic)
        assertNotNull(caverphone.caverphone("ball"));
    }

    @Test
    public void testCaverphone_SpecificSequences() {
        // Test w3
        assertNotNull(caverphone.caverphone("w3")); // '3' is removed by regex [^a-z]
        // Test wh3
        assertNotNull(caverphone.caverphone("wh3"));
        // Test r3
        assertNotNull(caverphone.caverphone("r3"));
        // Test l3
        assertNotNull(caverphone.caverphone("l3"));
    }
}
